["/assets/case-studies-D7Swu9NEx2.js"]},"/case-studies/$slug":$R[10]={preloads:$R[11]=["/assets/case-studies._slug-D0T8hA-hx2.js","/assets/primitives-DonnrdxC.js","/assets/CTABand-BVL83l97x2.js","/assets/Breadcrumbs-BLdoDYPpx2.js","/assets/StatBlock-B1BIWTih.js"]}}},matches:$R[12]=[$R[13]={i:"__root__␀",u:1788936464227,s:"success",ssr:!0},$R[14]={i:"␀case-studies␀case-studies",u:1788936464227,s:"success",ssr:!0},$R[15]={i:"␀case-studies␀$slug␀case-studies␀finance-operations-services-venture",u:1788936464227,s:"success",l:$R[16]={study:$R[17]={slug:"finance-operations-services-venture",name:"Finance & Operations Services Venture",sector:"Finance & Accounting Outsourcing (Proposed Venture)",location:"Ahmedabad, Gujarat",methodology:"Independent Feasibility Study — Full Scope",challenge:"Need market validation before capital commitment for subscription-based SMB finance outsourcing.",challengeFull:"A promoter group from Ahmedabad — with backgrounds in senior finance leadership in the pharma sector — wanted to establish a subscription-based finance and operations outsourcing firm for SMBs. Before committing capital, they wanted ten specific questions answered: filtered market size, willingness to switch, current spend, willingness to pay, talent availability, regulatory constraints, competitive threats, and the conditions under which the venture should not proceed. The brief explicitly requested an uncomfortable finding delivered plainly over a comfortable one delivered gently. SBC accepted that standard.",approach:"Three-phase feasibility: market validation, pressure test, and go-forward pricing design.",approachFull:"SBC conducted a structured three-phase feasibility study. Phase 1 validated the market — sizing the opportunity bottom-up from GSTN taxpayer data (not survey extrapolation), mapping competitors, and conducting 46 structured SMB interviews across Ahmedabad. Phase 2 pressure-tested the venture — regulatory scope review under the Chartered Accountants Act, competitive threat modelling over 24–36 months, operational and capital stress tests, and a written deal-breaker register. Phase 3 refined the go-forward design — three-tier pricing architecture anchored against real alternatives, customer priority sequencing, and a phased implementation roadmap.",stats:$R[18]=[$R[19]={value:"~5.6L",label:"Target Enterprises (SAM)"},$R[20]={value:"80%",label:"SMB Switching Openness"},$R[21]={value:"Feasible",label:"Verdict"}],bullets:$R[22]=["Market Size — Gujarat SAM: ~5.6 lakh target-band enterprises. Year-3 SOM: 150–300 clients (capacity-constrained, not market-constrained).","Primary Research — 80% of surveyed SMBs expressed openness to switching. Top barrier: trust, not price. 71.7% prefer monthly retainer model.","Competitive Landscape — No organised domestic FAO competitor targets Ahmedabad SMBs at the proposed price points. Structural white space confirmed.","Regulatory Scope — Entire service portfolio — bookkeeping, GST/TDS, payroll, MIS — sits outside CA-reserved activities. Legally clear and workable.","Pricing Architecture — Three tiers validated against real alternatives: Starter ₹4,999/mo, Growth ₹9,999/mo, Scale ₹21,999/mo. Growth tier beats average current SMB spend of ₹11,402/mo."],facts:$R[23]=[$R[24]={label:"Client",value:"Promoter Group — Pharma Sector (Ahmedabad)"},$R[25]={label:"Study Duration",value:"40 Days"},$R[26]={label:"Methodology",value:"Three-Phase: Validation → Pressure Test → Refinement"}],badge:"Feasible — Conditional on Pre-Launch Actions"},group:$R[27]={key:"feasibility",heading:"Feasibility Studies",label:"Feasibility Studies",headingLine1:"Strategic",headingLine2:"Research",sectorShort:"Feasibility",sidebarLabel:"Key Findings",studies:$R[28]=[$R[17],$R[29]={slug:"specialty-cafe-green-coffee-venture",name:"Specialty Café & Green Coffee Venture",sector:"F&B — Specialty Coffee / Café Venture (Proposed)",location:"Gujarat (Vapi)",methodology:"Strategic Feasibility — Sourcing & Economics",challenge:"Determine sourcing economics (domestic vs. imported) before capital investment.",challengeFull:"A Vapi-based industrialist with a manufacturing background in corrugated packaging wanted to evaluate entry into the specialty coffee and café space. Before committing capital, they needed clarity on sourcing economics, the landed cost reality of imported versus domestic green coffee, a viable business model, and an honest go/no-go recommendation.",approach:"Global FOB pricing analysis, import duty mapping, landed-cost modeling, and competitive benchmarking.",approachFull:"SBC conducted a strategic feasibility assessment covering the full green coffee sourcing landscape. Primary and secondary research mapped global FOB prices across origins (Ethiopia, Kenya, Colombia, Tanzania, Brazil), Indian import duty structure under HS Code 0901.11, and domestic farmgate pricing across Karnataka, Kerala, Tamil Nadu, and Andhra Pradesh. Landed cost scenarios were modelled across sea FCL, sea LCL, and air freight. The study benchmarked Indian D2C coffee brands (Blue Tokai, Subko, CoffeeVerse) and global luxury models (Bacha Coffee, %Arabica, Nespresso) to identify viable positioning.",stats:$R[30]=[$R[31]={value:"~210–220%",label:"Import Duty (CIF)"},$R[32]={value:"50–65%",label:"Domestic Cost Advantage"},$R[33]={value:"80–90%",label:"Recommended Domestic Sourcing"}],bullets:$R[34]=["Import Reality — India's effective import duty burden is ~210–220% of CIF value. Best-case landed cost for imported green coffee: ₹880–1,200/kg — 3x domestic Arabica.","Domestic Advantage — Indian Arabica: ₹250–340/kg farmgate. Domestic sourcing delivers a 50–65% structural cost advantage before roasting.","Recommended Sourcing — 80–90% domestic (blends & core SKUs) + 10–20% imported (premium single-origin, limited edition only).","Import Viability Rule — Proceed with imports only if landed cost exceeds ₹1,000/kg AND the product can sell at ₹400–500/kg roasted wholesale or above."],facts:$R[35]=[$R[36]={label:"Client",value:"Industrialist Promoter — Corrugated Packaging Sector, Vapi"},$R[37]={label:"Scope",value:"Green Coffee Sourcing Economics, Market Positioning, Go/No-Go"},$R[38]={label:"Geography",value:"India — Gujarat (Primary Market)"}],badge:"Domestic-First Sourcing Strategy"}]}},ssr:!0}],lastMatchId:"␀case-studies␀$slug␀case-studies␀finance-operations-services-venture"})($R["tsr"]);$_TSR.e();document.currentScript.remove()</script><script type="module" async="" src="/assets/index-B8ml6QWKx2.js"></script></body></html>